(r, big) => {
    const n = big ? 16 : r.int(1, 8);
    if (r.bool()) return [r.arr(n, 1, big ? 10000 : 6), r.int(1, n)];
    // build a yes-instance: k groups that each sum to the same target
    const k = r.int(1, big ? 6 : 3), per = Math.floor(n / k);
    if (per === 0) return [r.arr(n, 1, 6), 1];
    const target = r.int(per, big ? 5000 : 9), nums = [];
    for (let g = 0; g < k; g++) {
      const parts = g === k - 1 ? n - per * (k - 1) : per;
      let left = target;
      if (left < parts) return [r.arr(n, 1, 6), 1];
      for (let p = 0; p < parts - 1; p++) {
        const x = r.int(1, left - (parts - 1 - p));
        nums.push(x);
        left -= x;
      }
      nums.push(left);
    }
    return [r.shuffle(nums), k];
  }

