function canSplitEvenly(nums: number[], k: number): boolean {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % k !== 0) return false;
  const target = total / k;
  const a = [...nums].sort((x, y) => y - x);
  if (a[0] > target) return false;
  const buckets = new Array<number>(k).fill(0);
  const place = (i: number): boolean => {
    if (i === a.length) return true;
    for (let b = 0; b < k; b++) {
      if (buckets[b] + a[i] <= target) {
        buckets[b] += a[i];
        if (place(i + 1)) return true;
        buckets[b] -= a[i];
      }
      if (buckets[b] === 0) break; // other empty buckets would repeat this branch
    }
    return false;
  };
  return place(0);
}

