class Solution:
    def canSplitEvenly(self, nums: List[int], k: int) -> bool:
        total = sum(nums)
        if total % k:
            return False
        target = total // k
        a = sorted(nums, reverse=True)
        if a[0] > target:
            return False
        buckets = [0] * k

        def place(i):
            if i == len(a):
                return True
            for b in range(k):
                if buckets[b] + a[i] <= target:
                    buckets[b] += a[i]
                    if place(i + 1):
                        return True
                    buckets[b] -= a[i]
                if buckets[b] == 0:
                    break  # other empty buckets would repeat this branch
            return False

        return place(0)

