function canSplitEvenly(nums: number[], k: number): boolean {
  const total = nums.reduce((a, b) => a + b, 0);
  if (total % k !== 0) return false;
  const target = total / k, n = nums.length, full = (1 << n) - 1;
  const fill = new Int32Array(1 << n).fill(-1);
  fill[0] = 0;
  for (let mask = 0; mask <= full; mask++) {
    if (fill[mask] < 0) continue;
    for (let i = 0; i < n; i++) {
      const next = mask | (1 << i);
      if (next === mask || fill[next] >= 0) continue;
      if (fill[mask] + nums[i] <= target) fill[next] = (fill[mask] + nums[i]) % target;
    }
  }
  return fill[full] === 0;
}

